mapper.select:
SELECT srd.id, srd.main_id, srd.sku_id, srd.sku_no, srd.sales_qty, srd.return_qty, srd.return_type_dict, srd.remark, srd.source_detail_id, sr.approve_status FROM so_return_detail srd INNER JOIN so_return sr ON srd.main_id = sr.id AND srd.is_deleted = FALSE WHERE sr.is_deleted = FALSE AND sr.invalid_status = FALSE
and sr.source_id in
#{id}

SELECT srd.id, srd.main_id, srd.sku_id, srd.sku_no, srd.sales_qty, srd.return_qty, srd.return_type_dict, srd.return_reason_dict, srd.remark, srd.source_detail_id, sr.approve_status, srd.return_amount, srd.tax_return_amount, srd.return_amount_local_currency, srd.tax_return_amount_local_currency FROM so_return_detail srd INNER JOIN so_return sr ON srd.main_id = sr.id AND srd.is_deleted = FALSE WHERE sr.is_deleted = FALSE AND sr.invalid_status = FALSE
and srd.id in
#{id}

SELECT srd.ID, srd.main_id, sr.source_id, srd.sku_id, srd.sku_no, si.warehouse_org_id AS inventoryOrgId, CASE WHEN sd.qty > 0 THEN sd.qty ELSE 0 END AS salesQty, CASE WHEN sd.amount > 0 THEN sd.amount ELSE 0 END AS salesAmount, sd.is_gift, sd.is_close, srd.remark, sr.warehouse_id, sr.currency, sr.currency_Symbol, si.ID AS soId, srd.return_type_dict, srd.return_reason_dict, sr.customer_id, srd.platform_sku_no FROM so_return sr INNER JOIN so_return_detail srd ON srd.main_id = sr.ID AND srd.is_deleted =FALSE LEFT JOIN so_info si ON sr.source_id = si.ID AND si.is_deleted = FALSE LEFT JOIN so_detail sd ON srd.source_detail_id = sd.ID AND sd.is_deleted = FALSE AND sd.is_close = FALSE WHERE sr.is_deleted =FALSE
AND sr.id = #{dto.id}
AND srd.sku_no IN
#{skuNo}
AND srd.sku_no ILIKE concat('%',#{dto.remoteSearchSku}::text,'%')
